/**
 * Course data for the SQL & PostGIS course, generated by SQL inside the course database (no dumps in the repo).
 *
 * Determinism: no random(); every "random" choice is `knife_admin.rnd(stream, i)`, an md5 of the stream and row
 * number, so the same SEED_VERSION always builds the same rows on every machine and Postgres version.
 * Licence: everything is synthetic except public facts (Polish city names, approximate centre coordinates, rounded
 * populations). Chains and people are invented. Region polygons are rough rectangles, NOT real borders.
 *
 * Bump SEED_VERSION whenever this file changes: `ensureSeeded` (db.ts) rebuilds both schemas when the stored version differs.
 */

export const SEED_VERSION = 3;

